using System;

namespace StdbModule;

public static partial class ItalianQuotes
{
    public static class GianniRodari
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://it.wikiquote.org/wiki/Gianni_Rodari", Text = "È difficile fare le cose difficili: parlare al sordo mostrare la rosa al cieco. Bambini, imparate a fare le cose difficili: dare la mano al cieco, cantare per il sordo, liberare gli schiavi che si credono liberi.", Author = "Gianni Rodari" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gianni_Rodari", Text = "Io credo che le fiabe, quelle vecchie e quelle nuove, possano contribuire a educare la mente. La fiaba è il luogo di tutte le ipotesi: essa ci può dare delle chiavi per entrare nella realtà per strade nuove, può aiutare il bambino a conoscere il mondo.", Author = "Gianni Rodari" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gianni_Rodari", Text = "Le fiabe sono alleate dell'utopia, non della conservazione. E perciò noi le difendiamo: perché crediamo nel valore educativo dell'utopia, passaggio obbligato dall'accettazione passiva del mondo, alla capacità di criticarlo, all'impegno per trasformarlo.", Author = "Gianni Rodari" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gianni_Rodari", Text = "Nel paese della bugia, la verità è una malattia.", Author = "Gianni Rodari" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gianni_Rodari", Text = "Quanto pesa una lacrima? Secondo: la lacrima di un bambino capriccioso pesa meno del vento, quella di un bambino affamato pesa più di tutta la terra.", Author = "Gianni Rodari" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gianni_Rodari", Text = "Vale la pena che un bambino impari piangendo quello che può imparare ridendo? Se si mettessero insieme le lagrime versate nei cinque continenti per colpa dell'ortografia, si otterrebbe una cascata da sfruttare per la produzione dell'energia elettrica. Ma io trovo che sarebbe un'energia troppo costosa.", Author = "Gianni Rodari" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gianni_Rodari", Text = "Gli errori sono necessari, utili come il pane e spesso anche belli: per esempio la torre di Pisa.", Author = "Gianni Rodari" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gianni_Rodari", Text = "Che belle parole se si potesse scrivere con un raggio di sole. Che parole d'argento se si potesse scrivere con un filo di vento. Ma in fondo al calamaio c'è un tesoro nascosto e chi lo pesca scriverà parole d'oro col più nero inchiostro.", Author = "Gianni Rodari" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gianni_Rodari", Text = "Chiedo scusa alla favola antica se non mi piace l'avara formica io sto dalla parte della cicala che il più bel canto non vende... regala!", Author = "Gianni Rodari" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gianni_Rodari", Text = "Chissà se la luna di Kiev è bella come la luna di Roma, chissà se è la stessa o soltanto sua sorella... Ma son sempre quella! – la luna protesta – non sono mica un berretto da notte sulla tua testa! Viaggiando quassù faccio lume a tutti quanti, dall'India al Perù, dal Tevere al Mar Morto, e i miei raggi viaggiano senza passaporto.", Author = "Gianni Rodari" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gianni_Rodari", Text = "Filastrocca del gregario corridore proletario, che ai campioni di mestiere deve far da cameriere, e sul piatto, senza gloria, serve loro la vittoria.", Author = "Gianni Rodari" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gianni_Rodari", Text = "Non si può essere mai sicuri di quello che un bambino impara guardando la televisione. E non si deve mai sottovalutare la sua capacità di reagire creativamente al visibile.", Author = "Gianni Rodari" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gianni_Rodari", Text = "Non c'è vita dove non c'è lotta.", Author = "Gianni Rodari" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gianni_Rodari", Text = "Nelle nostre scuole, generalmente parlando, si ride troppo poco. L'idea che l'educazione della mente debba essere una cosa tetra è tra le più difficili da combattere.", Author = "Gianni Rodari" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gianni_Rodari", Text = "Il mondo si può guardare a altezza d'uomo, ma anche dall'alto di una nuvola (con gli aeroplani è più facile). Nella realtà si può entrare dalla porta principale o infilarvisi – è più divertente – da un finestrino.", Author = "Gianni Rodari" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gianni_Rodari", Text = "Se un bambino scrive nel suo quaderno «l'ago di Garda», ho la scelta tra correggere l'errore con un segnaccio rosso o blu, o seguirne l'ardito suggerimento e scrivere la storia e la geografia di questo «ago» importantissimo, segnato anche nella carta d'Italia. La Luna si specchierà sulla punta o nella cruna? Si pungerà il naso?", Author = "Gianni Rodari" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gianni_Rodari", Text = "Un «libbro» con due b sarà soltanto un libro più pesante degli altri, o un libro sbagliato, o un libro specialissimo?", Author = "Gianni Rodari" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gianni_Rodari", Text = "Sbagliando s'impara, è un vecchio proverbio. Il nuovo potrebbe essere che sbagliando s'inventa.", Author = "Gianni Rodari" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gianni_Rodari", Text = "Burattinaio, il più bel mestiere del mondo.", Author = "Gianni Rodari" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gianni_Rodari", Text = "Tra il mondo dei giocattoli e il mondo adulto c'è un rapporto meno chiaro di quanto possa sembrare a prima vista: da un lato, i giocattoli vi approdato «per caduta», dall'altro per conquista.", Author = "Gianni Rodari" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gianni_Rodari", Text = "Certe cose che nel mondo adulto hanno avuto un tempo grande importanza, accettano la riduzione a giocattoli, pur di non sparire, quando quel tempo viene a finire.", Author = "Gianni Rodari" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gianni_Rodari", Text = "Inventare storie con i giocattoli è quasi naturale, è una cosa che viene da sola se si gioca con i bambini: la storia non è che un prolungamento, uno sviluppo, un'esplosione festosa del giocattolo.", Author = "Gianni Rodari" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gianni_Rodari", Text = "L'incontro decisivo tra i ragazzi e i libri avviene sui banchi di scuola. Se avviene in una situazione creativa, dove conta la vita e non l'esercizio, ne potrà sorgere quel gusto della lettura col quale non si nasce perché non è un istinto. Se avviene in una situazione burocratica, se il libro sarà mortificato a strumento di esercitazioni (copiature, riassunti, analisi grammaticale eccetera), soffocato dal meccanismo tradizionale: «interrogazione-giudizio», ne potrà nascere la tecnica nella lettura, ma non il gusto. I ragazzi sapranno leggere, ma leggeranno solo se obbligati.", Author = "Gianni Rodari" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gianni_Rodari", Text = "L'immaginazione del bambino, stimolata a inventare parole, applicherà ai suoi strumenti su tutti i tratti dell'esperienza che sfideranno il suo intervento creativo. Le fiabe servono alla matematica come la matematica serve alle fiabe. Servono alla poesia, alla musica, all'utopia, all'impegno politico: insomma, all'uomo intero, e non solo al fantasticatore.", Author = "Gianni Rodari" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gianni_Rodari", Text = "La mente è una sola. La sua creatività va coltivata in tutte le direzioni.", Author = "Gianni Rodari" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gianni_Rodari", Text = "Con un po' di esercizio è possibile prendere lezioni di ottimismo anche da Giacomo Leopardi.", Author = "Gianni Rodari" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gianni_Rodari", Text = "Prima di tutto la fiaba è per il bambino uno strumento ideale per trattenere con sé l'adulto.", Author = "Gianni Rodari" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gianni_Rodari", Text = "Per colpa di un accento un tale di Santhià credeva d'essere alla meta ed era appena a metà.", Author = "Gianni Rodari" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gianni_Rodari", Text = "Cipollone ed i suoi figli abitavano in una baracca di legno, poco più grande di una cassetta di quelle che si vedono dall'ortolano. I ricchi che capitavano da quelle parti torcevano il naso disgustati.", Author = "Gianni Rodari" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gianni_Rodari", Text = "C'era una volta un tamburino che tornava dalla guerra. Era povero, aveva soltanto il suo tamburo, ma era contento lo stesso perché tornava a casa dopo tanti anni. Lo si sentiva suonare di lontano: barabàn, barabàn, barabàn...", Author = "Gianni Rodari" },
        };
    }
}